package com.example.shop.domain;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;

@Entity
public class Parcel {

    @Id
    private Long id;

    private String name;

    private String color;
}

package com.example.shop.domain;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface ParcelRepository extends JpaRepository<Parcel, Long> {
    List<Parcel> findByName(String name);
}

package com.example.shop.web;

import com.example.shop.domain.Parcel;
import com.example.shop.dto.ParcelDto;
import org.mapstruct.Mapper;

@Mapper(componentModel = "spring")
public interface ParcelMapper {
    ParcelDto toDto(Parcel parcel);

    Parcel toEntity(ParcelDto dto);
}

package com.example.shop.dto;

public record ParcelDto(
        Long id,
        String name
) {
}

package com.example.shop.service;

import com.example.shop.domain.Parcel;
import java.util.List;
import org.springframework.stereotype.Service;
import com.example.shop.web.ParcelMapper;
import org.springframework.beans.factory.annotation.Autowired;

@Service
public class ParcelService {

    @Autowired
    private ParcelMapper helper;
}
